'use client'
import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react'
import { Button } from '@/react/components/ui/Button'
import { Logo } from '@/react/components/visuals/Logo'
import { DispersionField } from '@/react/components/visuals/DispersionField'
import { PRODUCT_HERO_CSS, createHeroLight, startResultsRun, watchHeroLight, type HeroResult, type HeroSet } from '@/lib/product-hero'
import { ASCII_TEXTURE } from '@/lib/textures'
import { WORKS_STILLS } from '@/lib/works-light'
import { cn } from '@/react/lib/cn'

// The site's product hero (pages/Products/ProductHero and ResultsRun): the product's name in the page head type and its
// line centered, a White and a quiet button (stacked full width on phones), then the composer (a #262626 card with the
// 20px corner in a #4D4D4D hairline: the question, a caret, the attach square, the MCP chip with the logomark and the
// send square, White while there is text) over a row of result cards turned away in perspective (192px, 144 on phones;
// up to five from 768 to 1279). The run types each question at a human pace and flicks its row in, lets it drift while
// it is read and flicks it out as the question is erased (lib/product-hero.ts). A card under a mouse, or focused, turns
// to face you and comes forward, and its detail rises in over a dark scrim, one fact after another; the run eases to a
// stop meanwhile. Lit (the default): the site's works light behind it, fading out at the foot (its pre-drawn still; with
// `live`, the dispersion field over it, which the cards push and stir as they flick and drift, and the still fades out
// once it draws); unlit: the ASCII texture in the margins from 1024. Reduced motion:
// the first question and row stay still and the cards do not turn.
export type { HeroResult, HeroSet } from '@/lib/product-hero'

export interface ProductHeroAction { label: string; href: string }

export interface ProductHeroProps {
  /** The product's name: the page's h1. */
  name: string
  /** One line on what it does. */
  line: string
  primary?: ProductHeroAction
  secondary?: ProductHeroAction
  /** One question and its results per set, run in order. */
  sets: HeroSet[]
  /** The works light behind the hero (true) or the texture in its margins (false). */
  lit?: boolean
  /** The site's live light over the still: the dispersion field (composition works), which the result cards push and
   * stir as they move; the still fades out once it draws. */
  live?: boolean
  /** Your own live light over the still instead (it does not follow the cards). */
  light?: ReactNode
  /** The composer's hint while it is empty. */
  placeholder?: string
  /** The chip's label. */
  tool?: string
  /** Prefix for ids. */
  id?: string
  className?: string
}

function Card({ result, id }: { result: HeroResult; id: string }) {
  const { picture, pair, stat, notes, mark, label, meta, detail } = result
  const detailId = `${id}-${result.id}-detail`
  return (
    <li data-card="" tabIndex={0} aria-describedby={detailId} className="ds-ph-card relative flex-none outline-none">
      <div className="ds-ph-turn">
        <div data-face="" className={cn('ds-ph-face relative flex aspect-4/5 overflow-hidden rounded-ds-sm bg-surface-raised', pair ? 'gap-px' : '')}>
          {picture && <span className="relative flex-[1_1_0]"><img src={picture.src} alt={picture.alt} className="absolute inset-0 size-full object-cover" /></span>}
          {pair && <span className="relative flex-[1_1_0]"><img src={pair.src} alt={pair.alt} className="absolute inset-0 size-full object-cover" /></span>}
          {!picture && stat && (
            <span className="flex flex-[1_1_0] flex-col justify-end gap-2 p-4">
              <span className="ds-ph-stat-value text-fg">{stat.value}</span>
              <span className="type-ui text-fg-soft">{stat.caption}</span>
            </span>
          )}
          {notes?.length ? (
            <span className="absolute inset-x-2 bottom-2 flex flex-col items-start gap-1">
              {notes.map((n) => <span key={n} className="max-w-full rounded-panel bg-surface-subtle px-2 py-1 type-ui text-fg">{n}</span>)}
            </span>
          ) : null}
          <div id={detailId} data-detail="" className="ds-ph-detail pointer-events-none absolute inset-0 z-1 flex flex-col justify-end gap-3 overflow-hidden p-4">
            <p className="ds-ph-reveal flex-none truncate type-ui-strong text-fg" style={{ '--i': 0 } as CSSProperties}>{detail.title}</p>
            <dl className="m-0 flex flex-none flex-col gap-3">
              {detail.facts.map((f, i) => (
                <div key={f.term} data-fact="" className="ds-ph-reveal ds-ph-fact flex flex-none flex-col gap-1" style={{ '--i': i + 1 } as CSSProperties}>
                  <dt className="type-caption text-fg-soft">{f.term}</dt>
                  <dd className="m-0 type-ui text-fg">{f.value}</dd>
                </div>
              ))}
            </dl>
          </div>
        </div>
      </div>
      <p className="ds-ph-label mt-3 flex flex-col gap-1 px-3 type-ui">
        <span className="flex items-center gap-2 overflow-hidden font-medium text-ellipsis whitespace-nowrap text-fg">
          {mark && <img src={mark} alt="" width={20} height={20} className="size-5 flex-none rounded-ds-sm" />}
          {label}
        </span>
        {meta && <span className="text-fg-muted">{meta}</span>}
      </p>
    </li>
  )
}

export function ProductHero({
  name,
  line,
  primary = { label: 'Get a free API key', href: '#' },
  secondary = { label: 'Read the docs', href: '#' },
  sets,
  lit = true,
  live = false,
  light,
  placeholder = 'Ask about any brand’s ads',
  tool = 'MCP',
  id = 'product',
  className,
}: ProductHeroProps) {
  const runRef = useRef<HTMLDivElement>(null)
  const heroRef = useRef<HTMLElement>(null)
  const liveRef = useRef<HTMLSpanElement>(null)
  const [bridge] = useState(() => createHeroLight(() => liveRef.current?.querySelector('canvas') ?? null))
  const glows = lit && (live || !!light)
  const questions = sets.map((s) => s.question)
  const key = questions.join('\n')
  useEffect(() => {
    const run = runRef.current
    if (!run) return
    return startResultsRun(run, key.split('\n'), lit && live ? bridge : undefined)
  }, [key, lit, live, bridge])
  useEffect(() => {
    const hero = heroRef.current
    if (!hero || !glows) return
    return watchHeroLight(hero, () => liveRef.current?.querySelector('canvas') ?? null)
  }, [glows])

  return (
    <section ref={heroRef} data-ds="product-hero" aria-labelledby={`${id}-heading`} className={cn('ds-ph relative isolate overflow-x-clip pb-(--ds-layout-section) text-fg', className)}>
      <style href="ds-product-hero" precedence="ds">{PRODUCT_HERO_CSS(ASCII_TEXTURE)}</style>
      {!lit && <span aria-hidden="true" className="ds-ph-ascii" />}
      <div className="mx-auto flex max-w-(--ds-ph-head-w) flex-col items-center gap-6 px-(--ds-layout-gutter) pt-30 text-center">
        <h1 id={`${id}-heading`} className="max-w-180 type-section">{name}</h1>
        <p className="max-w-(--ds-layout-measure) type-body-lg text-pretty text-fg-soft">{line}</p>
        <div className="flex flex-wrap justify-center gap-3 max-md:flex-col max-md:self-stretch">
          <Button href={primary.href}>{primary.label}</Button>
          <Button href={secondary.href} variant="secondary">{secondary.label}</Button>
        </div>
      </div>
      <div ref={runRef} data-ph-run="" className="mt-10 flex flex-col items-center">
        <div aria-hidden="true" className="ds-ph-composer flex flex-col gap-3 rounded-ds-lg border border-edge-surface bg-surface-raised p-3">
          <p className="min-h-12 px-2 pt-2 type-body text-fg">
            <span data-ph-text="" />
            <span className="ds-ph-caret" />
            <span data-ph-hint="" hidden className="text-fg-muted">{placeholder}</span>
          </p>
          <div className="flex items-center gap-2">
            <span className="grid size-8 flex-none place-items-center rounded-panel border border-edge-surface text-fg-soft">
              <svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"><path d="M8 3v10M3 8h10" /></svg>
            </span>
            <span className="inline-flex h-8 items-center gap-2 rounded-panel bg-surface-inset px-3 type-ui-strong text-fg-soft">
              <Logo variant="mark" height={16} label="" className="text-fg" />
              {tool}
            </span>
            <span data-ph-send="" data-awake="" className="ds-ph-send ml-auto grid size-8 flex-none place-items-center rounded-panel bg-surface-inset text-fg-faint">
              <svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M8 13V3M3.5 7.5 8 3l4.5 4.5" /></svg>
            </span>
          </div>
        </div>
        <p className="sr-only">{questions.join(' ')}</p>
        <div data-stage="" className="ds-ph-stage mt-12 grid pt-6 pb-16">
          {sets.map((set) => (
            <ul key={set.question} data-row="" role="list" aria-label={set.resultsLabel} className="ds-ph-row m-0 flex list-none justify-center gap-2 p-0">
              {set.results.map((r) => <Card key={r.id} result={r} id={id} />)}
            </ul>
          ))}
        </div>
      </div>
      {lit && (
        <picture aria-hidden="true" className="ds-ph-light ds-ph-still">
          {WORKS_STILLS.slice(0, -1).map((s) => <source key={s.width} media={s.media} srcSet={s.picture} />)}
          <img src={WORKS_STILLS[WORKS_STILLS.length - 1].picture} alt="" draggable={false} />
        </picture>
      )}
      {glows ? (
        <span ref={liveRef} aria-hidden="true" className="ds-ph-light">
          {live ? <DispersionField composition="works" seed={7} drag={bridge.source} className="absolute inset-0 size-full" /> : light}
        </span>
      ) : null}
    </section>
  )
}

export default ProductHero

// The product hero's results run (site pages/Products/ResultsRun.tsx), framework-free so both flavors run the same
// clock. A question is typed into the composer at a human pace (a seeded rhythm per question, faster on common letter
// pairs, slower after spaces and on capitals), its row of result cards flicks in from the right on the site's flick
// curve, drifts left slowly (8px a second) while it is read, then flicks out to the left as the question is erased, and
// the next question begins. A card under the pointer, or focus inside the stage, eases the clock to a stop (200ms) so
// the card can be read; it runs again on leaving. It runs only while on screen and the tab is visible; with reduced
// motion the first question and its row stay still. Each card's detail drops facts from the end until it fits.
//
// The DOM it drives (both flavors render it): the run [data-ph-run] holding the composer's text [data-ph-text], its
// hint [data-ph-hint] and send button [data-ph-send], and the stage [data-stage] with one [data-row] per question, each
// with [data-card] items whose [data-face] holds a [data-detail] (a title, then [data-fact] items).

import type { DragSource } from '@/lib/effects/field-drag'

export interface HeroPicture { src: string; alt: string }

/** Cards per row the live light follows (the site's SLOTS). */
const SLOTS = 8

/**
 * The bridge between the run and a live light (the site's lightBridge): `source` goes to the dispersion field's `drag`
 * at once, and the run plugs its card boxes in while it runs, so the cards push and stir the light as they flick and
 * drift. `origin` returns the field's canvas, the box the cards are measured against.
 */
export interface HeroLight {
	source: DragSource
	plug: (next: DragSource | null) => void
	origin: () => Element | null
}

export function createHeroLight(origin: () => Element | null): HeroLight {
	let live: DragSource | null = null
	const source: DragSource = {
		now: () => live?.now() ?? 0,
		rects: (ms, out) => live?.rects(ms, out) ?? 0,
		pace: () => live?.pace?.() ?? 1,
	}
	return { source, plug: (next) => (live = next), origin }
}

/**
 * Marks the hero `data-live` once the live light's canvas has drawn (data-ready), so the pre-drawn still under it
 * fades out (the site's .hero:has(> canvas.field[data-ready]) > .still). `find` returns the canvas, which a web
 * component's light renders a moment later; it is looked for on each frame for up to two seconds.
 */
export function watchHeroLight(hero: HTMLElement, find: () => HTMLCanvasElement | null): () => void {
	let mo: MutationObserver | null = null
	let raf = 0
	let tries = 0
	const look = () => {
		const canvas = find()
		if (!canvas) {
			if (tries++ < 120) raf = requestAnimationFrame(look)
			return
		}
		const sync = () => hero.toggleAttribute('data-live', canvas.dataset.ready === 'true')
		sync()
		mo = new MutationObserver(sync)
		mo.observe(canvas, { attributes: true, attributeFilter: ['data-ready'] })
	}
	look()
	return () => {
		cancelAnimationFrame(raf)
		mo?.disconnect()
		hero.removeAttribute('data-live')
	}
}

export interface HeroResult {
	id: string
	/** The card's picture (4:5). */
	picture?: HeroPicture
	/** A second picture beside the first (a pair). */
	pair?: HeroPicture
	/** A figure instead of a picture. */
	stat?: { value: string; caption: string }
	/** Chips at the foot of the picture. */
	notes?: string[]
	/** A 20px mark beside the label. */
	mark?: string
	label: string
	meta?: string
	/** What turns up on hover or focus: a title and facts. */
	detail: { title: string; facts: { term: string; value: string }[] }
}

export interface HeroSet {
	question: string
	/** The row's accessible name. */
	resultsLabel: string
	results: HeroResult[]
}

// Pacing, from the site's tokens (ms): --dur-loop-flick, --dur-ph-hold, --dur-caret-blink / 2, --dur-read-hold,
// --dur-read-lead-later, --read-type-later; --search-drift (px a second); the erase step and the gap between
// questions from HeroVideo/reference (1.25 and 24 frames at 60fps).
const CHANGE = 1400
const HOLD = 7000
const CARET_REST = 530
const READ_HOLD = 2800
const LEAD_LATER = 400
const LATER_PACE = 0.8
const DRIFT = 8 / 1000
const ERASE = (1.25 * 1000) / 60
const GAP = (24 * 1000) / 60

// The site's flick (v3/V3Search/conveyor.ts): a fast middle that settles long.
const FLICK = [0, 0.0043, 0.0091, 0.0144, 0.0201, 0.0263, 0.033, 0.0411, 0.0493, 0.0589, 0.0694, 0.0814, 0.0948, 0.1097, 0.1266, 0.1468, 0.1702, 0.1989, 0.2334, 0.2784, 0.3373, 0.4153, 0.502, 0.5755, 0.6317, 0.675, 0.7103, 0.7394, 0.7643, 0.7859, 0.8045, 0.8213, 0.8366, 0.8495, 0.8619, 0.8735, 0.8835, 0.8932, 0.9018, 0.9101, 0.9175, 0.9242, 0.9307, 0.9367, 0.9422, 0.9473, 0.9521, 0.9569, 0.9607, 0.9645, 0.9683, 0.9712, 0.9746, 0.9774, 0.9802, 0.9828, 0.9847, 0.9866, 0.9885, 0.9905, 0.9919, 0.9933, 0.9943, 0.9957, 0.9964, 0.9971, 0.9981, 0.9986, 0.9991, 0.9993, 0.9995, 0.9998, 1]

export function flick(u: number) {
	if (u <= 0) return 0
	if (u >= 1) return 1
	const f = u * (FLICK.length - 1)
	const i = Math.floor(f)
	return FLICK[i] + (FLICK[i + 1] - FLICK[i]) * (f - i)
}

// The site's human typing (components/humanTyping.ts): when each key lands, in ms from the first.
const ROLLS = new Set(['th', 'he', 'in', 'er', 'an', 're', 'on', 'at', 'en', 'nd', 'ha', 'es', 'ng', 'st', 'as', 'or', 'ou', 'ea'])
const REACH = /[A-Z0-9?.,!’'"\-:;()&@#%]/
function seeded(seed: number) {
	let a = seed >>> 0
	return () => {
		a = (a + 0x6d2b79f5) >>> 0
		let t = a
		t = Math.imul(t ^ (t >>> 15), t | 1)
		t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
		return ((t ^ (t >>> 14)) >>> 0) / 4294967296
	}
}
function seedOf(text: string) {
	let h = 0x811c9dc5
	for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 0x01000193)
	return h >>> 0
}
export function keystrokes(text: string, pace = 1): number[] {
	const chars = [...text]
	const r = seeded(seedOf(text))
	const out: number[] = []
	let at = 0
	chars.forEach((ch, k) => {
		if (k > 0) {
			const prev = chars[k - 1]
			let ms: number
			if (ROLLS.has(prev + ch) && r() < 0.55) ms = 60 + r() * 12
			else {
				ms = 68 + r() * 36
				if (prev === ' ') ms += 36 + r() * 32
				if (ch === ' ') ms += 8 + r() * 16
				if (REACH.test(ch)) ms += 24 + r() * 28
				ms = Math.min(160, Math.max(60, ms))
			}
			at += ms * pace
		}
		out.push(Math.round(at))
	})
	return out
}

// A card's detail drops facts from the end until its title clears the top padding and nothing overflows.
function fitDetails(root: ParentNode) {
	for (const detail of root.querySelectorAll<HTMLElement>('[data-detail]')) {
		const title = detail.firstElementChild as HTMLElement | null
		if (!title) continue
		const top = parseFloat(getComputedStyle(detail).paddingTop) || 0
		const facts = [...detail.querySelectorAll<HTMLElement>('[data-fact]')]
		facts.forEach((f) => f.removeAttribute('data-cut'))
		const over = () => title.offsetTop < top - 0.5 || detail.scrollHeight > detail.clientHeight + 0.5
		for (let i = facts.length - 1; i >= 0 && over(); i -= 1) facts[i].setAttribute('data-cut', '')
	}
}

interface Cycle { typeAt: number[]; arrive: number; landed: number; leave: number; len: number }

/**
 * Starts the run inside `run` for these questions (one per row, in order); returns the function that stops it. With
 * `light` (createHeroLight), the cards' boxes feed the live light's drag.
 */
export function startResultsRun(run: HTMLElement, questions: string[], light?: HeroLight): () => void {
	const stage = run.querySelector<HTMLElement>('[data-stage]')
	const textEl = run.querySelector<HTMLElement>('[data-ph-text]')
	const hint = run.querySelector<HTMLElement>('[data-ph-hint]')
	const send = run.querySelector<HTMLElement>('[data-ph-send]')
	if (!stage || !textEl || questions.length === 0) return () => {}
	const rows = [...stage.querySelectorAll<HTMLElement>('[data-row]')]
	const reduced = window.matchMedia('(prefers-reduced-motion: reduce)')

	const lengthOf = (q: string, leave: number) => Math.max(leave + q.length * ERASE, leave + CHANGE) + GAP
	const cycles: Cycle[] = questions.map((q) => {
		const typeAt = keystrokes(q, LATER_PACE).map((k) => k + LEAD_LATER)
		const arrive = typeAt[0] ?? 0
		const landed = arrive + CHANGE
		const leave = Math.max(landed + HOLD, (typeAt[typeAt.length - 1] ?? 0) + READ_HOLD)
		return { typeAt, arrive, landed, leave, len: lengthOf(q, leave) }
	})
	const first = cycles[0]
	const start = Math.max((first.typeAt[first.typeAt.length - 1] ?? 0) + CARET_REST, first.landed)
	first.leave = Math.max(first.leave, start + HOLD)
	first.len = lengthOf(questions[0], first.leave)
	const loopLen = cycles.reduce((s, c) => s + c.len, 0)

	let span = 0
	const bias = rows.map(() => 0)
	const placed = rows.map(() => 0)
	const boxes: number[][][] = rows.map(() => [])
	let boxed = false
	const measure = () => {
		let widest = 0
		const middle = stage.getBoundingClientRect().left + stage.clientWidth / 2
		const origin = light?.origin()?.getBoundingClientRect()
		boxed = !!origin
		rows.forEach((row, i) => {
			const faces = [...row.querySelectorAll<HTMLElement>('[data-face]')].map((c) => c.getBoundingClientRect()).filter((b) => b.width > 0)
			if (faces.length === 0) return
			const left = Math.min(...faces.map((b) => b.left))
			const right = Math.max(...faces.map((b) => b.right))
			widest = Math.max(widest, right - left)
			bias[i] = (left + right) / 2 - middle - placed[i]
			boxes[i] = origin ? faces.slice(0, SLOTS).map((b) => [b.left - origin.left - placed[i], b.top - origin.top, b.width, b.height]) : []
		})
		span = stage.clientWidth / 2 + widest / 2
		fitDetails(stage)
	}

	const frameAt = (at: number) => {
		if (reduced.matches) return { text: questions[0], run: { index: 0, x: bias[0] }, moving: false, typing: false }
		let index = 0
		let t = at % loopLen
		while (t >= cycles[index].len) {
			t -= cycles[index].len
			index += 1
		}
		const c = cycles[index]
		const glide = at < first.len ? bias[0] - DRIFT * (t - start) : -DRIFT * (t - (c.landed + c.leave) / 2)
		const q = questions[index]
		const shown = t < c.leave ? c.typeAt.filter((a) => a <= t).length : q.length - Math.floor((t - c.leave) / ERASE)
		let x: number | null = null
		let moving = false
		if (t >= c.arrive && t < c.landed) {
			x = (1 - flick((t - c.arrive) / CHANGE)) * span + glide
			moving = true
		} else if (t >= c.landed && t < c.leave) x = glide
		else if (t >= c.leave && t < c.leave + CHANGE) {
			x = -flick((t - c.leave) / CHANGE) * span + glide
			moving = true
		}
		const lastChar = c.typeAt[c.typeAt.length - 1] ?? 0
		const typing = (t >= (c.typeAt[0] ?? 0) && t < lastChar + CARET_REST) || (t >= c.leave && t < c.leave + q.length * ERASE + CARET_REST)
		return { text: q.slice(0, Math.max(shown, 0)), run: x === null ? null : { index, x }, moving, typing }
	}

	let clock = start
	let lastText: string | null = null
	let moving = false
	let typing = false
	const draw = () => {
		const frame = frameAt(clock)
		if (frame.text !== lastText) {
			lastText = frame.text
			textEl.textContent = frame.text
			hint?.toggleAttribute('hidden', frame.text.length > 0)
			send?.toggleAttribute('data-awake', frame.text.length > 0)
		}
		if (frame.moving !== moving) {
			moving = frame.moving
			stage.toggleAttribute('data-moving', moving)
		}
		if (frame.typing !== typing) {
			typing = frame.typing
			run.toggleAttribute('data-typing', typing)
		}
		rows.forEach((row, i) => {
			const on = frame.run?.index === i
			placed[i] = on && frame.run ? frame.run.x - bias[i] : 0
			row.style.visibility = on ? 'visible' : 'hidden'
			row.style.transform = on ? `translate3d(${placed[i].toFixed(2)}px, 0, 0)` : ''
		})
	}

	let hovered = 0
	let focused = false
	let pace = 1
	light?.plug({
		now: () => clock,
		rects: (at, out) => {
			if (!boxed && light?.origin()) measure()
			out.fill(Number.NaN)
			const r = frameAt(at).run
			if (r) {
				const offset = r.x - bias[r.index]
				boxes[r.index].forEach((b, j) => {
					const k = (r.index * SLOTS + j) * 4
					out[k] = b[0] + offset
					out[k + 1] = b[1]
					out[k + 2] = b[2]
					out[k + 3] = b[3]
				})
			}
			return rows.length * SLOTS
		},
		pace: () => pace,
	})
	let raf = 0
	let last = 0
	let running = false
	let inView = false
	const tick = (now: number) => {
		const dt = Math.min(now - last, 100)
		pace += ((hovered > 0 || focused ? 0 : 1) - pace) * Math.min(1, dt / 200)
		clock += dt * pace
		last = now
		draw()
		raf = requestAnimationFrame(tick)
	}
	const sync = () => {
		const on = !reduced.matches && inView && document.visibilityState === 'visible'
		if (on === running) return
		running = on
		run.toggleAttribute('data-running', on)
		cancelAnimationFrame(raf)
		if (on) {
			last = performance.now()
			raf = requestAnimationFrame(tick)
		}
	}

	const enter = () => (hovered += 1)
	const leaveCard = () => (hovered = Math.max(0, hovered - 1))
	const cards = [...stage.querySelectorAll<HTMLElement>('[data-card]')]
	cards.forEach((c) => {
		c.addEventListener('pointerenter', enter)
		c.addEventListener('pointerleave', leaveCard)
	})
	const rootNode = stage.getRootNode() as Document | ShadowRoot
	const onFocus = () => (focused = stage.contains(rootNode.activeElement))
	const onBlur = () => requestAnimationFrame(onFocus)
	stage.addEventListener('focusin', onFocus)
	stage.addEventListener('focusout', onBlur)

	measure()
	draw()
	const ro = new ResizeObserver(() => {
		measure()
		draw()
	})
	ro.observe(stage)
	document.fonts?.ready.then(() => fitDetails(stage))
	const io = new IntersectionObserver(([e]) => {
		inView = e.isIntersecting
		sync()
	})
	io.observe(run)
	document.addEventListener('visibilitychange', sync)
	const onReduced = () => {
		draw()
		sync()
	}
	reduced.addEventListener('change', onReduced)

	return () => {
		light?.plug(null)
		cancelAnimationFrame(raf)
		ro.disconnect()
		io.disconnect()
		cards.forEach((c) => {
			c.removeEventListener('pointerenter', enter)
			c.removeEventListener('pointerleave', leaveCard)
		})
		stage.removeEventListener('focusin', onFocus)
		stage.removeEventListener('focusout', onBlur)
		document.removeEventListener('visibilitychange', sync)
		reduced.removeEventListener('change', onReduced)
	}
}

// The hero's CSS (ProductHero.module.css and V3Search.module.css's composer), shared by both flavors. `ascii` is the
